//! The route-level IP + country verdict and the unknown client identity
//! against the reference engine (`check_route_ip_access`, `check_ip_access`).
//! `tests/data/route_country.json` was generated by running the reference,
//! never written by hand.

use std::collections::BTreeMap;
use std::net::IpAddr;

use guard_core_engine::geo::{GeoIpHandler, check_countries, parse_country_lists};
use guard_core_engine::ip_gate::{IpGateConfig, IpGateVerdict, RouteIpGate, RouteIpVerdict};
use serde_json::Value;

struct Countries(BTreeMap<String, String>);

impl GeoIpHandler for Countries {
    fn get_country(&self, ip: IpAddr) -> Option<String> {
        self.0.get(&ip.to_string()).cloned()
    }
}

fn table() -> Value {
    serde_json::from_str(include_str!("data/route_country.json")).expect("fixture")
}

fn lists(table: &Value, key: &str) -> Vec<Vec<String>> {
    table[key]
        .as_array()
        .expect(key)
        .iter()
        .map(|list| {
            list.as_array()
                .expect("list")
                .iter()
                .map(|v| v.as_str().expect("entry").to_owned())
                .collect()
        })
        .collect()
}

fn ips(table: &Value) -> Vec<Option<IpAddr>> {
    table["ips"]
        .as_array()
        .expect("ips")
        .iter()
        .map(|v| v.as_str().expect("ip").parse::<IpAddr>().ok())
        .collect()
}

fn handler(table: &Value) -> Countries {
    Countries(
        table["countries"]
            .as_object()
            .expect("countries")
            .iter()
            .filter_map(|(ip, country)| Some((ip.clone(), country.as_str()?.to_owned())))
            .collect(),
    )
}

fn verdicts(table: &Value, key: &str) -> Vec<char> {
    table[key].as_str().expect(key).chars().collect()
}

#[test]
fn route_access_matches_the_reference_table() {
    let table = table();
    let (route_lists, blocked, whitelist) = (
        lists(&table, "route_lists"),
        lists(&table, "blocked_countries"),
        lists(&table, "whitelist_countries"),
    );
    let want = verdicts(&table, "route");
    let handler = handler(&table);
    let mut row = 0;
    for rwl in &route_lists {
        for rbl in &route_lists {
            for bc in &blocked {
                for wc in &whitelist {
                    for ip in ips(&table) {
                        let gate = RouteIpGate::new(rwl, rbl).expect("lists");
                        let countries = parse_country_lists(wc, bc);
                        let got = gate.evaluate_access(ip, &countries, Some(&handler));
                        let expected = match want[row] {
                            'N' => RouteIpVerdict::Unrestricted,
                            'T' => RouteIpVerdict::Allowed,
                            _ => RouteIpVerdict::Denied,
                        };
                        assert_eq!(
                            got.verdict, expected,
                            "rwl={rwl:?} rbl={rbl:?} bc={bc:?} wc={wc:?} ip={ip:?}"
                        );
                        row += 1;
                    }
                }
            }
        }
    }
    assert_eq!(row, want.len());
}

#[test]
fn unknown_identity_global_matches_the_reference_table() {
    let table = table();
    let (glists, gcountries) = (
        lists(&table, "global_lists"),
        lists(&table, "global_whitelist_countries"),
    );
    let want = verdicts(&table, "global");
    let handler = handler(&table);
    let mut row = 0;
    for wl in &glists {
        for wc in &gcountries {
            let gate = IpGateConfig::new(wl, [] as [&str; 0], [] as [&str; 0]).expect("lists");
            let countries = parse_country_lists(wc, [] as [&str; 0]);
            for ip in ips(&table) {
                // The unknown identity: the IP gate, then the country
                // whitelist (a restrictive one blocks the unidentified).
                let allowed = ip.map_or_else(
                    || {
                        matches!(gate.evaluate_unknown(), IpGateVerdict::Allowed(_))
                            && wc.is_empty()
                    },
                    |ip| match gate.evaluate(ip) {
                        IpGateVerdict::Denied(_) => false,
                        IpGateVerdict::Allowed(decision) => {
                            check_countries(ip, &countries, &handler, decision.is_whitelisted)
                                .is_none()
                        }
                    },
                );
                assert_eq!(allowed, want[row] == 'T', "wl={wl:?} wc={wc:?} ip={ip:?}");
                row += 1;
            }
        }
    }
    assert_eq!(row, want.len());
}

#[test]
fn no_geo_handler_leaves_the_country_arm_without_a_verdict() {
    let gate = RouteIpGate::new([] as [&str; 0], [] as [&str; 0]).expect("lists");
    let countries = parse_country_lists(["US"], ["CN"]);
    let ip = "10.0.0.1".parse::<IpAddr>().ok();
    let access = gate.evaluate_access(ip, &countries, None);
    assert_eq!(access.verdict, RouteIpVerdict::Unrestricted);
    assert!(!access.country_whitelist_matched);
}

#[test]
fn a_country_whitelist_match_reports_the_skip_flag() {
    let gate = RouteIpGate::new([] as [&str; 0], [] as [&str; 0]).expect("lists");
    let countries = parse_country_lists(["US"], [] as [&str; 0]);
    let handler = Countries(BTreeMap::from([("10.0.0.1".to_owned(), "US".to_owned())]));
    let ip = "10.0.0.1".parse::<IpAddr>().ok();
    let access = gate.evaluate_access(ip, &countries, Some(&handler));
    assert_eq!(access.verdict, RouteIpVerdict::Allowed);
    assert!(access.country_whitelist_matched);
}
